#include <bits/stdc++.h>
using namespace std;
class Solution {public:bool matchReplacement(string s,string sub,vector<vector<char>>& mappings){bool ok[128][128]={};for(auto& v:mappings)ok[(int)v[0]][(int)v[1]]=true;for(int i=0;i+(int)sub.size()<=(int)s.size();++i){bool good=true;for(int j=0;j<(int)sub.size();++j)if(s[i+j]!=sub[j]&&!ok[(int)sub[j]][(int)s[i+j]]){good=false;break;}if(good)return true;}return false;}};
